var n=`1131-cornbread`;var t=`world-1131`;var r=`US`;var s=`northern-america`;var a=8;var o=44;var d={en:`Cornbread`,ua:`Кукурудзяний хліб`};var l={en:`Cornbread is a dish from United States prepared with cornmeal, all-purpose flour, baking powder, chicken egg. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кукурудзяний хліб, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: кукурудзяна крупа дрібного помелу, пшеничне борошно універсальне, розпушувач тіста, куряче яйце. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`cornmeal`,285,`g`],[`all-purpose-flour`,170,`g`],[`baking-powder`,13,`g`],[`table-salt`,6,`g`]]},{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:7,i:[[`chicken-egg`,2,`pcs`],[`buttermilk`,390,`ml`],[`unsalted-butter`,85,`g`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 25 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 25 хвилин до готовності.`,t:[`baking`],m:25,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`honey`,40,`g`]]}];var g={slug:n,id:t,country:`US`,region:s,servings:8,minutes:44,title:d,text:l,steps:h};export{r as country,g as default,t as id,o as minutes,s as region,a as servings,n as slug,h as steps,l as text,d as title};